WITH ranked AS (SELECT symbol, trade_date, box_width_40, trend_slope_40, r_squared_40, style_label, style_confidence, ROW_NUMBER() OVER (PARTITION BY symbol ORDER BY trade_date DESC) AS rn FROM feat_style_daily WHERE trade_date <= ?) SELECT symbol, trade_date, box_width_40, trend_slope_40, r_squared_40, style_label, style_confidence FROM ranked WHERE rn=1 ORDER BY box_width_40 ASC NULLS LAST, symbol;
